// Common questions from new employees (in production these come from a form, Slack or a help desk queue).
const questions = [
  'How do I reset my password?',
  'What is the meal limit when travelling?',
  'When do I enrol in benefits?',
  'Can I paste customer data into an AI tool?',
  'Is there a parental leave top-up?'
];
return questions.map(question => ({ json: { question } }));

// One digest item: each question with the best answer and its source, or a flag for the AI Enablement team.
const rows = $input.all().map(item => {
  const top = item.json.results[0];
  return top
    ? { question: item.json.query, answer: top.snippet, source: top.source, answered: true }
    : { question: item.json.query, answer: 'Not in the knowledge base yet: flagged for the AI Enablement team.', source: null, answered: false };
});
const answered = rows.filter(r => r.answered).length;
const text = rows.map((r, i) => `${i + 1}. ${r.question}\n   ${r.answer}${r.source ? `\n   Source: ${r.source}` : ''}`).join('\n\n');
return [{ json: { answered, total: rows.length, gaps: rows.filter(r => !r.answered).map(r => r.question), digest: text, rows } }];
